    @Column(name = "forward_after")
    private Long forwardAfter;

    protected Rate() {
    }

    public Rate(String sheetId, Grade grade, LocalDate from, LocalDate to, BigDecimal pct) {
        this(sheetId, grade, from, to, pct, null);
    }

    public Rate(String sheetId, Grade grade, LocalDate from, LocalDate to, BigDecimal pct, Long forwardAfter) {
        this.forwardAfter = forwardAfter;
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        this.to = to;
        setPct(pct);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Grade getGrade() {
        return grade;
    }

    /** The date the rate is in force from, or null when it applies from the beginning of time. */
    public LocalDate getFrom() {
        return from;
    }

    /** The last date the rate is in force, or null when it runs until the grade's next rate. */
    public LocalDate getTo() {
        return to;
    }

    public void setTo(LocalDate to) {
        this.to = to;
    }

    public BigDecimal getPct() {
        return pct;
    }

    /** Change the percent; it is kept to two decimals. */
    public void setPct(BigDecimal pct) {
        this.pct = pct.setScale(2);
    }

    /** How many versions the rate has had; the one it holds is the newest. */
    public int getVersion() {
        return version;
    }

    /** Set the rate again: the value it held stays as an older version (its change), and this becomes
     *  the newest version, the one in force. */
    public void newVersion(BigDecimal pct, LocalDate to, Long forwardAfter) {
        this.forwardAfter = forwardAfter;
        setPct(pct);
        setTo(to);
        version++;
